import hashlib, hmac, json, policy_signing

def _sign(bundle, key=b"testkey"):
    payload = json.dumps({k: v for k, v in bundle.items() if k != "_sig"},
                          sort_keys=True, default=str, separators=(",", ":")).encode()
    return hmac.new(key, payload, hashlib.sha256).hexdigest()

def test_verify_bundle_accepts_valid_signature(monkeypatch):
    monkeypatch.setenv("POLICY_SIGNING_KEY", "testkey")
    bundle = {"rules": [1, 2], "_sig_alg": "HMAC-SHA256"}
    bundle["_sig"] = _sign(bundle)
    assert policy_signing.verify_bundle(bundle) is True

def test_verify_bundle_rejects_tampered_payload(monkeypatch):
    monkeypatch.setenv("POLICY_SIGNING_KEY", "testkey")
    bundle = {"rules": [1, 2], "_sig_alg": "HMAC-SHA256"}
    bundle["_sig"] = _sign(bundle)
    bundle["rules"] = [1, 2, 3]  # tamper after signing
    assert policy_signing.verify_bundle(bundle) is False

def test_verify_bundle_rejects_wrong_algorithm_field(monkeypatch):
    monkeypatch.setenv("POLICY_SIGNING_KEY", "testkey")
    bundle = {"rules": [], "_sig_alg": "MD5", "_sig": "whatever"}
    assert policy_signing.verify_bundle(bundle) is False

def test_verify_bundle_fails_closed_when_no_signing_key(monkeypatch):
    monkeypatch.delenv("POLICY_SIGNING_KEY", raising=False)
    bundle = {"rules": [], "_sig_alg": "HMAC-SHA256", "_sig": "x"}
    assert policy_signing.verify_bundle(bundle) is False

def test_verify_bundle_rejects_non_dict_input():
    assert policy_signing.verify_bundle("not a dict") is False  # type: ignore[arg-type]
